    12→func bytesToBlob(blob []byte) *GoKZG.Blob {
    13→	var ret GoKZG.Blob
    14→	copy(ret[:], blob)
    15→	return &ret
    16→}
    17→
    18→func bytesToCommitment(commitment []byte) (ret GoKZG.KZGCommitment) {
    19→	copy(ret[:], commitment)
    20→	return
    21→}
    22→
    23→func bytesToKZGProof(proof []byte) (ret GoKZG.KZGProof) {
    24→	copy(ret[:], proof)
    25→	return
    26→}
    27→
    28→// Verify performs single or batch verification of commitments depending on the number of given BlobSidecars.
    29→func Verify(blobSidecars ...blocks.ROBlob) error {
    30→	if len(blobSidecars) == 0 {
    31→		return nil
    32→	}
    33→	if len(blobSidecars) == 1 {
    34→		return kzgContext.VerifyBlobKZGProof(
    35→			bytesToBlob(blobSidecars[0].Blob),
    36→			bytesToCommitment(blobSidecars[0].KzgCommitment),
    37→			bytesToKZGProof(blobSidecars[0].KzgProof))
    38→	}
    39→	blobs := make([]GoKZG.Blob, len(blobSidecars))
    40→	cmts := make([]GoKZG.KZGCommitment, len(blobSidecars))
    41→	proofs := make([]GoKZG.KZGProof, len(blobSidecars))
    42→	for i, sidecar := range blobSidecars {
    43→		blobs[i] = *bytesToBlob(sidecar.Blob)
    44→		cmts[i] = bytesToCommitment(sidecar.KzgCommitment)
    45→		proofs[i] = bytesToKZGProof(sidecar.KzgProof)
    46→	}
    47→	return kzgContext.VerifyBlobKZGProofBatch(blobs, cmts, proofs)
    48→}
    49→
    50→// VerifyBlobKZGProofBatch verifies KZG proofs for multiple blobs using batch verification.
    51→// This is more efficient than verifying each blob individually when len(blobs) > 1.
    52→// For single blob verification, it uses the optimized single verification path.
    53→func VerifyBlobKZGProofBatch(blobs [][]byte, commitments [][]byte, proofs [][]byte) error {
    54→	if len(blobs) != len(commitments) || len(blobs) != len(proofs) {
    55→		return errors.Errorf("number of blobs (%d), commitments (%d), and proofs (%d) must match", len(blobs), len(commitments), len(proofs))
    56→	}
    57→
    58→	if len(blobs) == 0 {
    59→		return nil
    60→	}
    61→
    62→	// Optimize for single blob case - use single verification to avoid batch overhead
    63→	if len(blobs) == 1 {
    64→		return kzgContext.VerifyBlobKZGProof(
    65→			bytesToBlob(blobs[0]),
    66→			bytesToCommitment(commitments[0]),
    67→			bytesToKZGProof(proofs[0]))
    68→	}
    69→
    70→	// Use batch verification for multiple blobs
    71→	ckzgBlobs := make([]ckzg4844.Blob, len(blobs))
    72→	ckzgCommitments := make([]ckzg4844.Bytes48, len(commitments))
    73→	ckzgProofs := make([]ckzg4844.Bytes48, len(proofs))
    74→
    75→	for i := range blobs {
    76→		if len(blobs[i]) != len(ckzg4844.Blob{}) {
    77→			return fmt.Errorf("blobs len (%d) differs from expected (%d)", len(blobs[i]), len(ckzg4844.Blob{}))
    78→		}
    79→		if len(commitments[i]) != len(ckzg4844.Bytes48{}) {
    80→			return fmt.Errorf("commitments len (%d) differs from expected (%d)", len(commitments[i]), len(ckzg4844.Blob{}))
    81→		}
    82→		if len(proofs[i]) != len(ckzg4844.Bytes48{}) {
    83→			return fmt.Errorf("proofs len (%d) differs from expected (%d)", len(proofs[i]), len(ckzg4844.Blob{}))
    84→		}
    85→		ckzgBlobs[i] = ckzg4844.Blob(blobs[i])
    86→		ckzgCommitments[i] = ckzg4844.Bytes48(commitments[i])
    87→		ckzgProofs[i] = ckzg4844.Bytes48(proofs[i])
    88→	}
    89→
    90→	valid, err := ckzg4844.VerifyBlobKZGProofBatch(ckzgBlobs, ckzgCommitments, ckzgProofs)
    91→	if err != nil {
    92→		return errors.Wrap(err, "batch verification")
    93→	}
    94→	if !valid {
    95→		return errors.New("batch KZG proof verification failed")
    96→	}
    97→
    98→	return nil
    99→}
